u_ai_tool.u_parameters:
{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "The name of the skill to load (e.g., 'servicenow-calendar', 'incident-analysis')"
    }
  },
  "required": [
    "name"
  ]
}

u_ai_tool.u_script:
(function(args, userId) {
  if (!args || !args.name) {
    return { error: 'Skill name is required' };
  }

  var skillGR = new GlideRecord('u_ai_skill');
  skillGR.addQuery('u_name', args.name);
  skillGR.addQuery('u_active', true);
  skillGR.setLimit(1);
  skillGR.query();

  if (!skillGR.next()) {
    // Return list of available skills for error context
    var availableGR = new GlideRecord('u_ai_skill');
    availableGR.addQuery('u_active', true);
    availableGR.query();
    var available = [];
    while (availableGR.next()) {
      available.push({
        name: '' + availableGR.u_name,
        description: '' + availableGR.u_description
      });
    }

    return { 
      error: 'Skill not found: ' + args.name,
      available_skills: available
    };
  }

  return {
    loaded: true,
    skill_name: '' + skillGR.u_name,
    skill_description: '' + skillGR.u_description,
    content: '' + skillGR.u_content
  };
})(args, userId);
